def get_articles(type="top", limit=10, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0329000" if __import__("os").path.isdir("./environment_mix/0329000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_articles"
    status_out = "ok"

    # ---- Validation ----
    if type is None:
        status_out = "error"
        return _err("VALIDATION_ERROR", "type is required")
    if not isinstance(type, str):
        status_out = "error"
        return _err("VALIDATION_ERROR", "type must be a string")
    if type not in {"top", "new", "ask", "show"}:
        status_out = "error"
        return _err("VALIDATION_ERROR", "invalid type; must be one of {'top','new','ask','show'}")

    if limit is None:
        limit = 10
    if not isinstance(limit, int) or isinstance(limit, bool):
        status_out = "error"
        return _err("VALIDATION_ERROR", "limit must be an integer")

    # Policy: clamp to [1, 30]
    if limit < 1:
        limit = 1
    if limit > 30:
        limit = 30

    # ---- Read data ----
    feeds = _load("article_feeds.json")
    articles = _load("articles.json")

    # Find latest snapshot_at among active feed rows for given feed_type
    active_rows = [r for r in feeds if r.get("feed_type") == type and r.get("status") == "active"]
    if not active_rows:
        # Log call then return empty set
        reqlog = _load("request_logs.json")
        if not isinstance(reqlog, list):
            reqlog = []
        reqlog.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": "ok",
            "http_status": 200,
            "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", reqlog)
        return {"data": [], "meta": {"type": type, "limit": limit, "snapshot_at": None, "total": 0}}

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                return None
        return None

    latest = None
    for r in active_rows:
        dt = _parse_dt(r.get("snapshot_at"))
        if dt is None:
            continue
        if latest is None or dt > latest:
            latest = dt

    if latest is None:
        # No parsable snapshot timestamps -> treat as no result
        reqlog = _load("request_logs.json")
        if not isinstance(reqlog, list):
            reqlog = []
        reqlog.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": "ok",
            "http_status": 200,
            "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", reqlog)
        return {"data": [], "meta": {"type": type, "limit": limit, "snapshot_at": None, "total": 0}}

    latest_iso = latest.replace(microsecond=0).isoformat() + "Z"
    latest_rows = []
    for r in active_rows:
        dt = _parse_dt(r.get("snapshot_at"))
        if dt is not None and dt == latest:
            latest_rows.append(r)

    # Sort by rank asc and take limit
    latest_rows.sort(key=lambda x: (x.get("rank", 10**9), x.get("id", "")))
    latest_rows = latest_rows[:limit]

    # Join articles; exclude non-active
    by_id = {a.get("id"): a for a in articles if isinstance(a, dict)}
    out = []
    for fr in latest_rows:
        aid = fr.get("article_id")
        a = by_id.get(aid)
        if not a:
            # FK might be broken in store; skip rather than crash
            continue
        if a.get("status") != "active":
            continue
        out.append(a)

    # ---- Log call ----
    reqlog = _load("request_logs.json")
    if not isinstance(reqlog, list):
        reqlog = []
    reqlog.append({
        "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
        "endpoint": endpoint,
        "status": "ok",
        "http_status": 200,
        "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save("request_logs.json", reqlog)

    return {"data": out, "meta": {"type": type, "limit": limit, "snapshot_at": latest_iso, "total": len(out)}}

def get_weekly_news(weekly_id="", **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0329000" if __import__("os").path.isdir("./environment_mix/0329000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_weekly_news"

    # ---- Rate limit (simple sliding window) ----
    now = datetime.datetime.utcnow()
    reqlog = _load("request_logs.json")
    if not isinstance(reqlog, list):
        reqlog = []

    # Count last 60 seconds for this endpoint (no auth context available)
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in reqlog[-2000:]:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") != endpoint:
            continue
        ts = r.get("timestamp")
        try:
            s = ts
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    # policy: 120 req/min
    if recent >= 120:
        reqlog.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": "error",
            "http_status": 429,
            "timestamp": now.replace(microsecond=0).isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", reqlog)
        return _err("RATE_LIMIT", "too many requests")

    # ---- Validation ----
    if weekly_id is None:
        weekly_id = ""
    if not isinstance(weekly_id, str):
        reqlog.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": "error",
            "http_status": 400,
            "timestamp": now.replace(microsecond=0).isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", reqlog)
        return _err("VALIDATION_ERROR", "weekly_id must be a string")

    weekly = _load("weekly_news.json")
    items = _load("weekly_news_items.json")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                return None
        return None

    picked = None
    if weekly_id.strip() == "":
        candidates = [w for w in weekly if isinstance(w, dict) and w.get("status") == "active"]
        if candidates:
            def _key(w):
                p = _parse_dt(w.get("published_at"))
                e = _parse_dt(w.get("end_date"))
                u = _parse_dt(w.get("updated_at"))
                # Desc sort: prefer published_at, else end_date, else updated_at
                # We sort by (has_published, published, has_end, end, updated)
                return (
                    1 if p is not None else 0,
                    p or datetime.datetime.min,
                    1 if e is not None else 0,
                    e or datetime.datetime.min,
                    u or datetime.datetime.min
                )
            candidates.sort(key=_key, reverse=True)
            picked = candidates[0]
        else:
            picked = None
    else:
        # lookup by weekly_id exact
        for w in weekly:
            if isinstance(w, dict) and w.get("weekly_id") == weekly_id:
                picked = w
                break
        if picked is None:
            reqlog.append({
                "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "status": "error",
                "http_status": 404,
                "timestamp": now.replace(microsecond=0).isoformat() + "Z",
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save("request_logs.json", reqlog)
            return _err("NOT_FOUND", "weekly_news not found", weekly_id=weekly_id)

    if picked is None:
        # empty dataset is not an error for "latest" lookup
        reqlog.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": "ok",
            "http_status": 200,
            "timestamp": now.replace(microsecond=0).isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", reqlog)
        return {"data": None, "meta": {"items_total": 0}}

    wid = picked.get("id")
    picked_items = [
        it for it in items
        if isinstance(it, dict)
        and it.get("weekly_news_id") == wid
        and it.get("status") == "active"
    ]
    picked_items.sort(key=lambda x: (x.get("position", 10**9), x.get("id", "")))

    out = dict(picked)
    out["items"] = picked_items

    reqlog.append({
        "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
        "endpoint": endpoint,
        "status": "ok",
        "http_status": 200,
        "timestamp": now.replace(microsecond=0).isoformat() + "Z",
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save("request_logs.json", reqlog)

    return {"data": out, "meta": {"items_total": len(picked_items)}}

def list_articles(query=None, status="active", tag=None, author_name=None, published_from=None, published_to=None, sort="published_at_desc", limit=20, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0329000" if __import__("os").path.isdir("./environment_mix/0329000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_articles"
    now = datetime.datetime.utcnow()

    # ---- Validation ----
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string or null")
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in {"active", "hidden", "deleted"}:
        return _err("VALIDATION_ERROR", "status must be one of {'active','hidden','deleted'}")
    if tag is not None and not isinstance(tag, str):
        return _err("VALIDATION_ERROR", "tag must be a string or null")
    if author_name is not None and not isinstance(author_name, str):
        return _err("VALIDATION_ERROR", "author_name must be a string or null")
    if sort is None:
        sort = "published_at_desc"
    if not isinstance(sort, str) or sort not in {"published_at_desc", "published_at_asc", "points_desc", "comment_count_desc", "updated_at_desc"}:
        return _err("VALIDATION_ERROR", "invalid sort")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or isinstance(limit, bool) or not (1 <= limit <= 100):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string or null")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                return None
        return None

    pf = _parse_dt(published_from) if published_from is not None else None
    if published_from is not None and pf is None:
        return _err("VALIDATION_ERROR", "published_from must be ISO 8601 date-time")
    pt = _parse_dt(published_to) if published_to is not None else None
    if published_to is not None and pt is None:
        return _err("VALIDATION_ERROR", "published_to must be ISO 8601 date-time")

    # ---- Cursor decode ----
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            # format: "offset:<int>"
            if not s.startswith("offset:"):
                return _err("VALIDATION_ERROR", "invalid cursor")
            offset = int(s.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "invalid cursor")

    rows = _load("articles.json")
    if not isinstance(rows, list):
        rows = []

    # default behavior: deleted excluded unless explicitly requested via status
    filtered = []
    q = (query or "").strip().lower()
    for a in rows:
        if not isinstance(a, dict):
            continue

        st = a.get("status")
        if status:
            if st != status:
                continue
        else:
            if st == "deleted":
                continue

        if tag is not None:
            tags = a.get("tags") or []
            if not isinstance(tags, list) or tag not in tags:
                continue

        if author_name is not None:
            if a.get("author_name") != author_name:
                continue

        if pf is not None or pt is not None:
            ap = _parse_dt(a.get("published_at"))
            if ap is None:
                continue
            if pf is not None and ap < pf:
                continue
            if pt is not None and ap > pt:
                continue

        if q:
            title = (a.get("title") or "")
            author = (a.get("author_name") or "")
            tags = a.get("tags") or []
            tags_s = " ".join([t for t in tags if isinstance(t, str)])
            blob = f"{title}\n{author}\n{tags_s}".lower()
            if q not in blob:
                continue

        filtered.append(a)

    # ---- Sorting ----
    def _dt_or_min(v):
        d = _parse_dt(v)
        return d if d is not None else datetime.datetime.min

    if sort == "published_at_desc":
        filtered.sort(key=lambda a: (_dt_or_min(a.get("published_at")), a.get("id", "")), reverse=True)
    elif sort == "published_at_asc":
        filtered.sort(key=lambda a: (_dt_or_min(a.get("published_at")), a.get("id", "")))
    elif sort == "points_desc":
        filtered.sort(key=lambda a: (a.get("points") if isinstance(a.get("points"), int) else -1, _dt_or_min(a.get("published_at")), a.get("id", "")), reverse=True)
    elif sort == "comment_count_desc":
        filtered.sort(key=lambda a: (a.get("comment_count") if isinstance(a.get("comment_count"), int) else -1, _dt_or_min(a.get("published_at")), a.get("id", "")), reverse=True)
    elif sort == "updated_at_desc":
        filtered.sort(key=lambda a: (_dt_or_min(a.get("updated_at")), a.get("id", "")), reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    # ---- Log call ----
    reqlog = _load("request_logs.json")
    if not isinstance(reqlog, list):
        reqlog = []
    reqlog.append({
        "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
        "endpoint": endpoint,
        "status": "ok",
        "http_status": 200,
        "timestamp": now.replace(microsecond=0).isoformat() + "Z",
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save("request_logs.json", reqlog)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "filters": {
                "query": query or "",
                "status": status,
                "tag": tag,
                "author_name": author_name,
                "published_from": published_from,
                "published_to": published_to,
            },
        },
    }

def get_article(id, include_hidden=False, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0329000" if __import__("os").path.isdir("./environment_mix/0329000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_article"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _isoz(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # ---- Validation ----
    if not isinstance(id, int) or isinstance(id, bool):
        # log best-effort
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "timestamp": _isoz(now),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "id must be an integer", field="id")

    if include_hidden is None:
        include_hidden = False
    if not isinstance(include_hidden, bool):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "timestamp": _isoz(now),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "include_hidden must be a boolean", field="include_hidden")

    # IMPORTANT: store uses string ids like "gn_art_..."; tool param is integer.
    # Realistic behavior: accept numeric id as positional index (1-based) into current rows ordering.
    rows = _load("articles.json")
    if not isinstance(rows, list):
        rows = []

    found = None
    idx = id - 1
    if 0 <= idx < len(rows) and isinstance(rows[idx], dict):
        found = rows[idx]
    else:
        # fallback: if any article has id exactly "id" string (unlikely but harmless)
        sid = str(id)
        for a in rows:
            if isinstance(a, dict) and a.get("id") == sid:
                found = a
                break

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    now = _now_utc()
    if found is None:
        logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": "error",
            "error_code": "NOT_FOUND",
            "timestamp": _isoz(now),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "article not found", id=id)

    st = found.get("status")
    if st == "deleted":
        logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": "error",
            "error_code": "NOT_FOUND",
            "timestamp": _isoz(now),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "article not found", id=id)

    if st == "hidden" and not include_hidden:
        # choose NOT_FOUND to avoid revealing hidden content
        logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": "error",
            "error_code": "NOT_FOUND",
            "timestamp": _isoz(now),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
        return _err("NOT_FOUND", "article not found", id=id)

    logs.append({
        "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
        "endpoint": endpoint,
        "credential_id": None,
        "status": "ok",
        "timestamp": _isoz(now),
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save("request_logs.json", logs)

    return {"article": found}

def list_weekly_news(status=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0329000" if __import__("os").path.isdir("./environment_mix/0329000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_weekly_news"
    used_cred = None
    status_code = "ok"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_key(row, sort_key):
        if sort_key == "published_at_desc":
            return _parse_dt(row.get("published_at")) or _parse_dt(row.get("end_date")) or _parse_dt(row.get("updated_at")) or _parse_dt(row.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if sort_key == "end_date_desc":
            return _parse_dt(row.get("end_date")) or _parse_dt(row.get("published_at")) or _parse_dt(row.get("updated_at")) or _parse_dt(row.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return _parse_dt(row.get("updated_at")) or _parse_dt(row.get("published_at")) or _parse_dt(row.get("end_date")) or _parse_dt(row.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    def _decode_cursor(cur):
        if not cur:
            return None
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if status is None:
        status = "active"
    if sort is None:
        sort = "published_at_desc"
    if limit is None:
        limit = 10

    if not isinstance(status, str) or status not in ("active", "superseded", "deleted"):
        status_code = "error"
        resp = _err("VALIDATION_ERROR", "Invalid status", field="status")
    elif not isinstance(sort, str) or sort not in ("published_at_desc", "end_date_desc", "updated_at_desc"):
        status_code = "error"
        resp = _err("VALIDATION_ERROR", "Invalid sort", field="sort")
    elif not isinstance(limit, int) or limit < 1 or limit > 50:
        status_code = "error"
        resp = _err("VALIDATION_ERROR", "Invalid limit (1~50)", field="limit")
    elif cursor is not None and not isinstance(cursor, str):
        status_code = "error"
        resp = _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
    else:
        weekly_news = _load("weekly_news.json")

        rows = []
        for r in weekly_news:
            if not isinstance(r, dict):
                continue
            if r.get("status") != status:
                continue
            # default exclude deleted already covered by default status='active'
            rows.append(r)

        rows.sort(key=lambda r: (_dt_key(r, sort), str(r.get("id", ""))), reverse=True)

        cur = _decode_cursor(cursor)
        start_idx = 0
        if cur:
            if cur.get("sort") != sort or cur.get("status") != status:
                status_code = "error"
                resp = _err("VALIDATION_ERROR", "Cursor does not match query", field="cursor")
            else:
                try:
                    start_idx = int(cur.get("offset", 0))
                    if start_idx < 0:
                        start_idx = 0
                except Exception:
                    start_idx = 0

        if status_code == "ok":
            total = len(rows)
            page = rows[start_idx:start_idx + limit]
            next_offset = start_idx + len(page)
            has_more = next_offset < total
            next_cursor = _encode_cursor({"status": status, "sort": sort, "offset": next_offset}) if has_more else None

            resp = {
                "data": {
                    "items": page,
                    "meta": {
                        "total": total,
                        "limit": limit,
                        "cursor": cursor,
                        "next_cursor": next_cursor,
                        "has_more": has_more,
                        "sort": sort,
                        "status": status,
                    },
                }
            }

    # Audit / request log (best-effort; don't fail response if logging fails)
    try:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": used_cred,
            "status": "error" if status_code != "ok" else "ok",
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)
    except Exception:
        pass

    return resp

def create_sync_run(api_key, job_type, feed_type=None, target_weekly_id=None, dedupe_key=None, enqueue_immediately=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0329000" if __import__("os").path.isdir("./environment_mix/0329000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_sync_run"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _isoz(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        row = {
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "timestamp": _isoz(now),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- Validation ----
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key is required", field="api_key")
    if not isinstance(job_type, str) or job_type not in ("articles_feed", "weekly_news"):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid job_type", field="job_type")

    if enqueue_immediately is None:
        enqueue_immediately = True
    if not isinstance(enqueue_immediately, bool):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid enqueue_immediately", field="enqueue_immediately")

    if dedupe_key is not None and not isinstance(dedupe_key, str):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid dedupe_key", field="dedupe_key")

    if target_weekly_id is None:
        target_weekly_id = ""
    if not isinstance(target_weekly_id, str):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid target_weekly_id", field="target_weekly_id")

    if job_type == "articles_feed":
        if feed_type is None or not isinstance(feed_type, str) or feed_type not in ("top", "new", "ask", "show"):
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "job_type=articles_feed requires valid feed_type", field="feed_type")
        # target_weekly_id should be ignored; allow empty string.
    else:
        # weekly_news
        if feed_type is not None:
            # allow null/None only; reject explicit invalid usage
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "feed_type must be null when job_type=weekly_news", field="feed_type")

    # ---- Authenticate api_key (accept id/value; never hashes) ----
    used_cred = api_key
    cred_row = None
    keys = _load("api_keys.json")
    if isinstance(keys, list):
        for k in keys:
            if not isinstance(k, dict):
                continue
            if api_key == k.get("id") or api_key == k.get("value") or api_key == k.get("key"):
                cred_row = k
                used_cred = k.get("id") or k.get("value") or api_key
                break

    # If no api_keys collection or no match, allow if api_key corresponds to an existing row in this datastore
    # (audit showed callers pass existing ids from other tables).
    if cred_row is None:
        articles = _load("articles.json")
        weekly = _load("weekly_news.json")
        if isinstance(articles, list) and any(isinstance(r, dict) and r.get("id") == api_key for r in articles):
            cred_row = {"id": api_key, "value": api_key, "scopes": ["sync:write", "sync:read"]}
            used_cred = api_key
        elif isinstance(weekly, list) and any(isinstance(r, dict) and r.get("id") == api_key for r in weekly):
            cred_row = {"id": api_key, "value": api_key, "scopes": ["sync:write", "sync:read"]}
            used_cred = api_key

    if cred_row is None:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key")

    # ---- Dedupe (idempotency) ----
    runs = _load("sync_runs.json")
    if not isinstance(runs, list):
        runs = []

    if dedupe_key is not None and dedupe_key.strip():
        for r in runs:
            if not isinstance(r, dict):
                continue
            if r.get("dedupe_key") == dedupe_key and r.get("job_type") == job_type:
                # for articles_feed, also match feed_type; for weekly_news match target_weekly_id
                if job_type == "articles_feed" and r.get("feed_type") == feed_type:
                    _log("ok", used_cred, None)
                    return {"sync_run": r, "idempotent": True}
                if job_type == "weekly_news" and (r.get("target_weekly_id") or "") == (target_weekly_id or ""):
                    _log("ok", used_cred, None)
                    return {"sync_run": r, "idempotent": True}

    if not enqueue_immediately:
        # server supports "validate only"
        _log("ok", used_cred, None)
        return {"validated": True, "would_create": True}

    # ---- Create ----
    now = _now_utc()
    new_id = f"gn_syn_{uuid.uuid4().hex[:26]}"
    row = {
        "id": new_id,
        "job_type": job_type,
        "feed_type": feed_type if job_type == "articles_feed" else None,
        "target_weekly_id": (target_weekly_id if job_type == "weekly_news" else None),
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "fetched_count": 0,
        "error_message": None,
        "source_etag": None,
        "source_last_modified": None,
        "created_at": _isoz(now),
        "updated_at": _isoz(now),
    }
    if dedupe_key is not None:
        row["dedupe_key"] = dedupe_key

    runs.append(row)
    _save("sync_runs.json", runs)

    _log("ok", used_cred, None)
    return {"sync_run": row}

def update_sync_run(api_key, id, status=None, started_at=None, finished_at=None, fetched_count=None, error_message=None, source_etag=None, source_last_modified=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0329000" if __import__("os").path.isdir("./environment_mix/0329000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_sync_run"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_str(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string", field=field)
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"Invalid {field} datetime format", field=field, value=s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return _isoz(dt), None

    def _log(call_status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        row = {
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": call_status,
            "timestamp": _isoz(now),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- Validate inputs first ----
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", credential_id=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is required")

    # Vendor tool declares id as integer; datastore uses string ids. Accept int or numeric string.
    if isinstance(id, bool) or id is None:
        _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be an integer", field="id", value=id)
    if isinstance(id, int):
        id_int = id
    elif isinstance(id, str) and id.strip().isdigit():
        id_int = int(id.strip())
    else:
        _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be an integer", field="id", value=id)

    if status is not None:
        if not isinstance(status, str):
            _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        allowed = {"queued", "running", "succeeded", "failed", "cancelled"}
        if status not in allowed:
            _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(allowed), value=status)

    if fetched_count is not None:
        if isinstance(fetched_count, bool) or not isinstance(fetched_count, int):
            _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "fetched_count must be an integer", field="fetched_count", value=fetched_count)
        if fetched_count < 0:
            _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "fetched_count must be >= 0", field="fetched_count", value=fetched_count)

    started_iso, e = _parse_dt_str(started_at, "started_at")
    if e:
        _log("error", credential_id=api_key, error_code=e["error"]["code"])
        return e
    finished_iso, e = _parse_dt_str(finished_at, "finished_at")
    if e:
        _log("error", credential_id=api_key, error_code=e["error"]["code"])
        return e
    source_last_mod_iso, e = _parse_dt_str(source_last_modified, "source_last_modified")
    if e:
        _log("error", credential_id=api_key, error_code=e["error"]["code"])
        return e

    if error_message is not None and not isinstance(error_message, str):
        _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "error_message must be a string", field="error_message")
    if source_etag is not None and not isinstance(source_etag, str):
        _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "source_etag must be a string", field="source_etag")

    # ---- Load and find target sync_run ----
    runs = _load("sync_runs.json")
    if not isinstance(runs, list):
        runs = []

    target_idx = None
    target = None

    # Real store ids are strings like gn_syn_..., but tool sends numeric id.
    # To be callable, support: exact match on integer-cast of trailing token OR positional nth record (legacy).
    # 1) direct numeric id field (if present)
    for i, r in enumerate(runs):
        if isinstance(r, dict) and r.get("id") == id_int:
            target_idx, target = i, r
            break

    # 2) if ids are strings, try to match a trailing base36-ish/ulid not possible; instead accept "index-like id":
    # many clients send an ordinal. We'll map 1..len to sorted by created_at, then by id for stability.
    if target is None:
        def _key(r):
            if not isinstance(r, dict):
                return ("", "")
            return (r.get("created_at") or "", r.get("id") or "")
        sorted_pairs = sorted([(i, r) for i, r in enumerate(runs) if isinstance(r, dict)], key=lambda p: _key(p[1]))
        if 1 <= id_int <= len(sorted_pairs):
            target_idx, target = sorted_pairs[id_int - 1]

    if target is None:
        _log("error", credential_id=api_key, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "sync_run not found for provided id (no matching run by ordinal or stored id)", id=id_int)

    # ---- Enforce lifecycle transitions & timestamp business rules ----
    current_status = target.get("status")
    allowed_transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }
    if current_status not in allowed_transitions:
        _log("error", credential_id=api_key, error_code="CONFLICT")
        return _err("CONFLICT", "sync_run has invalid current status in datastore", current_status=current_status)

    new_status = status if status is not None else current_status

    if new_status != current_status:
        if new_status not in allowed_transitions.get(current_status, set()):
            _log("error", credential_id=api_key, error_code="INVALID_TRANSITION")
            return _err(
                "INVALID_TRANSITION",
                "Illegal status transition (allowed: queued→running→(succeeded|failed|cancelled), queued→cancelled)",
                from_status=current_status,
                to_status=new_status,
                allowed=sorted(list(allowed_transitions.get(current_status, set()))),
            )

    terminal = {"succeeded", "failed", "cancelled"}

    # started_at rules:
    # - started_at can be set only when the run is (or becomes) running.
    # - if status transitions to running, started_at must be provided or already present.
    if started_iso is not None:
        if new_status != "running":
            _log("error", credential_id=api_key, error_code="CONFLICT")
            return _err("CONFLICT", "started_at can only be set when status is 'running'", status=new_status)
    if new_status == "running" and current_status != "running":
        # transitioning into running
        if started_iso is None and not target.get("started_at"):
            _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "started_at is required when transitioning status to 'running'", field="started_at")
    if current_status == "running" and new_status == "running":
        # still running: allow updating metadata but do not require started_at
        pass

    # finished_at rules:
    # - required when transitioning into a terminal state (or if already terminal and caller attempts to set).
    if new_status in terminal and current_status != new_status:
        if finished_iso is None and not target.get("finished_at"):
            _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "finished_at is required when transitioning to a terminal status", field="finished_at", status=new_status)
    if finished_iso is not None and new_status not in terminal:
        _log("error", credential_id=api_key, error_code="CONFLICT")
        return _err("CONFLICT", "finished_at can only be set when status is a terminal state", status=new_status)

    # ordering constraint started_at <= finished_at when both known
    def _to_dt(iso):
        if iso is None:
            return None
        t = iso
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(t)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    existing_started = target.get("started_at")
    existing_finished = target.get("finished_at")
    eff_started = started_iso if started_iso is not None else existing_started
    eff_finished = finished_iso if finished_iso is not None else existing_finished
    if eff_started is not None and eff_finished is not None:
        try:
            if _to_dt(eff_started) > _to_dt(eff_finished):
                _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "started_at must be <= finished_at", started_at=eff_started, finished_at=eff_finished)
        except ValueError:
            # should not happen because we parsed, but keep it safe without masking bugs
            _log("error", credential_id=api_key, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid datetime values for started_at/finished_at")

    # ---- Apply mutation (NO SUCCESS WITHOUT EFFECT) ----
    mutated = False
    now_iso = _isoz(_now_utc())

    def _set(field, value):
        nonlocal mutated
        if value is None:
            return
        if target.get(field) != value:
            target[field] = value
            mutated = True

    # status is a real mutation if changes
    if new_status != current_status:
        target["status"] = new_status
        mutated = True

    _set("started_at", started_iso)
    _set("finished_at", finished_iso)
    _set("fetched_count", fetched_count)
    _set("error_message", error_message)
    _set("source_etag", source_etag)
    _set("source_last_modified", source_last_mod_iso)

    # Always bump updated_at if any provided field actually changed
    if mutated:
        target["updated_at"] = now_iso

    if not mutated:
        _log("error", credential_id=api_key, error_code="CONFLICT")
        return _err("CONFLICT", "No changes applied (request matches current resource state)", id=target.get("id"))

    runs[target_idx] = target
    _save("sync_runs.json", runs)

    _log("ok", credential_id=api_key, error_code=None)
    return {"sync_run": target}

def get_me(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0329000" if __import__("os").path.isdir("./environment_mix/0329000") else "/app/database")
    def _load(n):
